import type { GridRowId, GridValidRowModel } from '@mui/x-data-grid';

/** Marker key for rows generated by the grid (groups, detail panels, skeletons). */
export const SYNTHETIC = Symbol.for('tecton-mui.DataGrid.synthetic');

/** Aggregates attached to a copy of a tree-data parent row. */
export const ROW_AGGREGATES = Symbol.for('tecton-mui.DataGrid.rowAggregates');

export function getRowAggregates(row: unknown): Record<string, unknown> | undefined {
  return row && typeof row === 'object'
    ? (row as { [ROW_AGGREGATES]?: Record<string, unknown> })[ROW_AGGREGATES]
    : undefined;
}

export type SyntheticKind = 'group' | 'detail' | 'skeleton';

export interface SyntheticMeta {
  kind: SyntheticKind;
  id: GridRowId;
  depth: number;
  /** group: grouping field (row grouping) or null (tree data auto-generated parent). */
  groupingField?: string | null;
  groupingKey?: unknown;
  childrenCount?: number;
  /** Aggregated values for group rows. */
  aggregates?: Record<string, unknown>;
  /** detail: id/row of the master row. */
  masterId?: GridRowId;
  masterRow?: GridValidRowModel;
  /** skeleton: index in the server dataset. */
  index?: number;
}

export type SyntheticRow = { [SYNTHETIC]: SyntheticMeta };

export function getSynthetic(row: unknown): SyntheticMeta | undefined {
  return row && typeof row === 'object' ? (row as Partial<SyntheticRow>)[SYNTHETIC] : undefined;
}

export const GROUP_ID_PREFIX = 'auto-generated-row-';
export const DETAIL_ID_SUFFIX = '-detail-panel';

/** Per-row metadata for tree-data rows that are real user rows (depth, children). */
export interface RowTreeMeta {
  depth: number;
  childrenCount: number;
  /** Tree data: label of the last path segment. */
  label?: string;
}

/** Visible row descriptor exposed by the pipeline. */
export interface VisibleRowInfo {
  id: GridRowId;
  depth: number;
  isGroup: boolean;
}
